import random
import string
from typing import List

# Generate valid URL-encoded strings intended for StringUtils::url_decode.
# Characteristics to cover:
# - Plain ASCII without encoding
# - Plus signs mapping to spaces
# - Percent-encoded bytes: hex pairs, mixed case
# - Multibyte UTF-8 sequences percent-encoded
# - Boundary sizes, including empty and near 4096 but kept smaller
# - Sequences of consecutive encodings
# - Reserved and unreserved characters
# - Query-like strings with '&' and '='
# - Already-decoded percent and plus signs
# Note: We avoid trailing incomplete % sequences per fuzzer stub precaution.

HEX_UP = "0123456789ABCDEF"
HEX_LO = "0123456789abcdef"
UNRESERVED = string.ascii_letters + string.digits + "-_.~"
RESERVED = ":/?#[]@!$&'()*+,;="
SPACE_CHARS = [" ", "\t"]


def _rand_hex_byte(rand: random.Random, mix_case: bool = True) -> str:
    b = rand.randrange(256)
    hi = (b >> 4) & 0xF
    lo = b & 0xF
    if mix_case and rand.random() < 0.5:
        return "%" + HEX_UP[hi] + HEX_LO[lo]
    else:
        table = HEX_UP if rand.random() < 0.5 else HEX_LO
        return "%" + table[hi] + table[lo]


def _percent_encode_byte(b: int, rand: random.Random) -> str:
    hi = (b >> 4) & 0xF
    lo = b & 0xF
    if rand.random() < 0.5:
        return "%" + HEX_UP[hi] + HEX_UP[lo]
    else:
        return "%" + HEX_LO[hi] + HEX_LO[lo]


def _rand_utf8_codepoint(rand: random.Random) -> str:
    # pick ranges to form valid UTF-8 when percent-encoded later
    r = rand.random()
    if r < 0.6:
        cp = rand.randrange(0x20, 0x7F)  # printable ASCII
    elif r < 0.8:
        cp = rand.randrange(0x80, 0x7FF)
    elif r < 0.95:
        cp = rand.randrange(0x800, 0xFFFF)
        # avoid surrogates
        if 0xD800 <= cp <= 0xDFFF:
            cp = 0xE000 + (cp - 0xD800)
    else:
        cp = rand.randrange(0x10000, 0x10FFFF)
    return chr(cp)


def _utf8_bytes(s: str) -> bytes:
    return s.encode('utf-8', 'strict')


def _percent_encode_bytes(buf: bytes, rand: random.Random) -> str:
    return ''.join(_percent_encode_byte(b, rand) for b in buf)


def _segment_plain(rand: random.Random, length: int) -> str:
    alphabet = UNRESERVED + RESERVED + "%+"  # include characters interesting to decoder
    return ''.join(rand.choice(alphabet) for _ in range(length))


def _segment_plus_spaces(rand: random.Random, length: int) -> str:
    out = []
    for _ in range(length):
        if rand.random() < 0.5:
            out.append('+')  # becomes space
        else:
            out.append(rand.choice(UNRESERVED))
    return ''.join(out)


def _segment_percent_ascii(rand: random.Random, count: int) -> str:
    # percent-encode ASCII including reserved and boundary values
    choices = [0x00, 0x09, 0x0A, 0x0D, 0x20, 0x25, 0x2B, 0x2F, 0x3F, 0x40, 0x5B, 0x5D, 0x7E]
    out = []
    for _ in range(count):
        b = rand.choice(choices) if rand.random() < 0.7 else rand.randrange(0, 128)
        out.append(_percent_encode_byte(b, rand))
    return ''.join(out)


def _segment_percent_utf8(rand: random.Random, count: int) -> str:
    # percent-encode random Unicode code points as UTF-8
    parts: List[str] = []
    for _ in range(count):
        cp = _rand_utf8_codepoint(rand)
        parts.append(_percent_encode_bytes(_utf8_bytes(cp), rand))
    return ''.join(parts)


def _segment_query(rand: random.Random, pairs: int) -> str:
    # Build k=v pairs with mixed percent-encodings and plus for spaces
    def rand_token() -> str:
        token = []
        length = rand.randint(1, 10)
        for _ in range(length):
            r = rand.random()
            if r < 0.4:
                token.append(rand.choice(UNRESERVED))
            elif r < 0.55:
                token.append('+')
            elif r < 0.85:
                token.append(_rand_hex_byte(rand))
            else:
                token.append(_percent_encode_byte(rand.randrange(256), rand))
        return ''.join(token)
    items = []
    for i in range(pairs):
        k = rand_token()
        v = rand_token()
        items.append(f"{k}={v}")
    return '&'.join(items)


def _segment_mixed(rand: random.Random, target_len: int) -> str:
    # Compose a mixture of the above segments to a target length (approximate)
    segs: List[str] = []
    while sum(len(s) for s in segs) < target_len:
        choice = rand.random()
        if choice < 0.15:
            segs.append(_segment_plain(rand, rand.randint(1, 12)))
        elif choice < 0.3:
            segs.append(_segment_plus_spaces(rand, rand.randint(2, 10)))
        elif choice < 0.55:
            segs.append(_segment_percent_ascii(rand, rand.randint(1, 6)))
        elif choice < 0.85:
            segs.append(_segment_percent_utf8(rand, rand.randint(1, 3)))
        else:
            segs.append(_segment_query(rand, rand.randint(1, 3)))
        if rand.random() < 0.3:
            segs.append(rand.choice(['/', '?', '#', ';', ',']))
    s = ''.join(segs)
    if len(s) > target_len:
        s = s[:target_len]
    return s


def _avoid_trailing_incomplete_percent(s: str) -> str:
    # Ensure last two chars are not an incomplete % sequence
    if not s:
        return s
    if s[-1] == '%':
        s = s[:-1] + 'X'
    if len(s) >= 2 and s[-2] == '%':
        s = s[:-2] + 'X' + s[-1]
    return s


def generate(seed: int) -> bytes:
    rand = random.Random(seed)

    # Decide overall strategy
    strat = rand.random()
    if strat < 0.08:
        s = ''  # empty
    elif strat < 0.18:
        # short simple string
        s = _segment_plain(rand, rand.randint(1, 8))
    elif strat < 0.30:
        # plus-heavy
        s = _segment_plus_spaces(rand, rand.randint(5, 40))
    elif strat < 0.45:
        # only percent ASCII
        s = _segment_percent_ascii(rand, rand.randint(4, 40))
    elif strat < 0.60:
        # only percent UTF-8
        s = _segment_percent_utf8(rand, rand.randint(2, 16))
    elif strat < 0.80:
        # query-like
        s = _segment_query(rand, rand.randint(1, 10))
    else:
        # mixed long but bounded
        target_len = rand.randint(32, 512)
        s = _segment_mixed(rand, target_len)

    # Occasionally prepend/append interesting prefixes/suffixes
    prefixes = [
        '',
        'http://',
        'https://',
        '/',
        '?',
    ]
    suffixes = [
        '',
        '/',
        '?a=%2B&b=%25',
        '#frag%20ment',
    ]
    if rand.random() < 0.5:
        s = rand.choice(prefixes) + s
    if rand.random() < 0.5:
        s = s + rand.choice(suffixes)

    s = _avoid_trailing_incomplete_percent(s)

    # Ensure maximum size
    if len(s) > 4096:
        s = s[:4096]

    return s.encode('utf-8', 'strict')
